INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13249, 'plPL', 'Przy odrobinie szczęścia Twierdza Drak\'Tharon, pozbawiona przywódcy, nie będzie już takim cierniem w boku tych, którzy walczą w tym regionie z Plagą.$b$b<Arcymag spogląda na tiki w twojej dłoni.>$b$bI dobrze, że tiki straciło swoje mojo. Nie miałbym pojęcia, jak go użyć, ani nawet czy wypada robić coś takiego.', 0);
