INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(15168, 'plPL', 'Wasze wysiłki... są daremne.', '', 0),
(26464, 'plPL', 'Powstańcie, moi wojownicy, i walczcie dla nowego pana!', '', 0),
(26473, 'plPL', 'Miłego towarzystwa! Król Lisz przesyła pozdrowienia!', '', 0),
(26474, 'plPL', 'Nie uciekajcie tak szybko! Mam dla was prezent na pożegnanie...', '', 0),
(26537, 'plPL', 'Wsparcie! Potrzebujemy wsparcia!', '', 0),
(26538, 'plPL', 'Pomocy, mon! Ich być za dużo!', '', 0),
(26932, 'plPL', 'Chłód, który czujecie, zwiastuje waszą zgubę!', '', 0),
(26933, 'plPL', 'Wzmocnijcie moją obronę! Prędzej, niech was licho!', '', 0),
(27777, 'plPL', 'Chyba widzicie, że to wszystko na próżno!', '', 0),
(28034, 'plPL', 'Wasze wysiłki... są daremne.', '', 0),
(28035, 'plPL', 'Taki los czeka każdego, kto sprzeciwi się Królowi Liszowi!', '', 0),
(29588, 'plPL', '%s wzywa pomocy!', '', 0),
(29606, 'plPL', 'Tharon\'ja widzi wszystko! Dzieło śmiertelników nie zakończy wiecznej dynastii!', '', 0),
(29611, 'plPL', 'Tak jak przepowiedział Tharon\'ja!', '', 0),
(29612, 'plPL', 'Tak, jak zostało zapisane!', '', 0),
(29613, 'plPL', 'Twoje ciało służy teraz Tharon\'ji!', '', 0),
(29614, 'plPL', 'Tharon\'ja znajdzie zastosowanie dla twojej śmiertelnej powłoki!', '', 0),
(29615, 'plPL', 'Nie! Ten smak... trwał zbyt krótko!', '', 0),
(29616, 'plPL', 'Aaach!! Tharon\'ja chce więcej!', '', 0),
(29617, 'plPL', 'To... niemożliwe! Tharon\'ja jest wieczny! Tharon\'ja... jest...', '', 0),
(30036, 'plPL', 'Poddajcie się wreszcie i gińcie!', '', 0),
(30041, 'plPL', 'Więcej flaków! Więcej krwi! Więcej żarcia!', '', 0),
(30042, 'plPL', 'Ja cię pokroić i zjeść!', '', 0),
(30043, 'plPL', 'Taki głodny! Musieć żreć!', '', 0),
(30044, 'plPL', 'Trup robić bum!', '', 0);
